import React, { useMemo, useState } from "react";

import ApplicationStepper from "./components/ApplicationStepper";
import LoanTypeSelection from "./components/LoanTypeSelection";

import {
  LOAN_TYPES,
  getLoanFormConfig,
} from "./config/loanForms";


const CreateApplication = () => {
  const [selectedLoanType, setSelectedLoanType] = useState("");

  const [currentStep, setCurrentStep] = useState(1);

  const [formData, setFormData] = useState({});

  const [addresses, setAddresses] = useState([
    {
      type: "",
      address: "",
    },
  ]);

  const [references, setReferences] = useState([
    {
      name: "",
      phone: "",
      relation: "",
      address: "",
    },
  ]);

  const [coApplicants, setCoApplicants] = useState([
    {
      name: "",
      phone: "",
      email: "",
      pan: "",
      relation: "",
    },
  ]);

  const loanConfig = useMemo(() => {
    if (!selectedLoanType) {
      return null;
    }

    return getLoanFormConfig(selectedLoanType);
  }, [selectedLoanType]);


  /*
  |--------------------------------------------------------------------------
  | Field Change
  |--------------------------------------------------------------------------
  */

  const handleFieldChange = (name, value) => {
    setFormData((previous) => ({
      ...previous,
      [name]: value,
    }));
  };


  /*
  |--------------------------------------------------------------------------
  | Loan Type
  |--------------------------------------------------------------------------
  */

  const handleLoanTypeChange = (loanType) => {
    setSelectedLoanType(loanType);

    setCurrentStep(2);

    setFormData({});
  };


  /*
  |--------------------------------------------------------------------------
  | Address
  |--------------------------------------------------------------------------
  */

  const handleAddressChange = (index, field, value) => {
    setAddresses((previous) =>
      previous.map((address, addressIndex) =>
        addressIndex === index
          ? {
              ...address,
              [field]: value,
            }
          : address
      )
    );
  };


  const addAddress = () => {
    const maxAddresses = loanConfig?.sections?.find(
      (section) => section.key === "addresses"
    )?.maxAddresses;

    if (maxAddresses && addresses.length >= maxAddresses) {
      return;
    }

    setAddresses((previous) => [
      ...previous,
      {
        type: "",
        address: "",
      },
    ]);
  };


  const removeAddress = (index) => {
    if (addresses.length === 1) {
      return;
    }

    setAddresses((previous) =>
      previous.filter((_, addressIndex) => addressIndex !== index)
    );
  };


  /*
  |--------------------------------------------------------------------------
  | Reference
  |--------------------------------------------------------------------------
  */

  const handleReferenceChange = (index, field, value) => {
    setReferences((previous) =>
      previous.map((reference, referenceIndex) =>
        referenceIndex === index
          ? {
              ...reference,
              [field]: value,
            }
          : reference
      )
    );
  };


  const addReference = () => {
    const maxReferences = loanConfig?.maxReferences || 5;

    if (references.length >= maxReferences) {
      return;
    }

    setReferences((previous) => [
      ...previous,
      {
        name: "",
        phone: "",
        relation: "",
        address: "",
      },
    ]);
  };


  const removeReference = (index) => {
    if (references.length === 1) {
      return;
    }

    setReferences((previous) =>
      previous.filter(
        (_, referenceIndex) => referenceIndex !== index
      )
    );
  };


  /*
  |--------------------------------------------------------------------------
  | Co-Applicant
  |--------------------------------------------------------------------------
  */

  const handleCoApplicantChange = (index, field, value) => {
    setCoApplicants((previous) =>
      previous.map((applicant, applicantIndex) =>
        applicantIndex === index
          ? {
              ...applicant,
              [field]: value,
            }
          : applicant
      )
    );
  };


  const addCoApplicant = () => {
    const maxCoApplicants = loanConfig?.maxCoApplicants || 5;

    if (coApplicants.length >= maxCoApplicants) {
      return;
    }

    setCoApplicants((previous) => [
      ...previous,
      {
        name: "",
        phone: "",
        email: "",
        pan: "",
        relation: "",
      },
    ]);
  };


  const removeCoApplicant = (index) => {
    if (coApplicants.length === 1) {
      return;
    }

    setCoApplicants((previous) =>
      previous.filter(
        (_, applicantIndex) => applicantIndex !== index
      )
    );
  };


  /*
  |--------------------------------------------------------------------------
  | Next / Back
  |--------------------------------------------------------------------------
  */

  const handleNext = () => {
    setCurrentStep((previous) => previous + 1);
  };


  const handleBack = () => {
    setCurrentStep((previous) =>
      Math.max(1, previous - 1)
    );
  };


  /*
  |--------------------------------------------------------------------------
  | Render Normal Field
  |--------------------------------------------------------------------------
  */

  const renderField = (field) => {
    const value = formData[field.name] ?? "";

    const commonProps = {
      id: field.name,
      name: field.name,
      value,
      onChange: (event) =>
        handleFieldChange(
          field.name,
          event.target.value
        ),
    };


    if (field.type === "textarea") {
      return (
        <textarea
          {...commonProps}
          placeholder={field.label}
          rows={4}
        />
      );
    }


    if (field.type === "select") {
      return (
        <select {...commonProps}>
          <option value="">
            {field.label}
          </option>

          {(field.options || []).map((option) => (
            <option
              key={option}
              value={option}
            >
              {option}
            </option>
          ))}
        </select>
      );
    }


    if (field.type === "radio") {
      return (
        <div className="radio-group">
          {(field.options || []).map((option) => (
            <label
              key={option}
              className="radio-option"
            >
              <input
                type="radio"
                name={field.name}
                value={option}
                checked={value === option}
                onChange={(event) =>
                  handleFieldChange(
                    field.name,
                    event.target.value
                  )
                }
              />

              <span>{option}</span>
            </label>
          ))}
        </div>
      );
    }


    if (field.type === "currency") {
      return (
        <div className="currency-field">
          <span className="currency-symbol">
            ₹
          </span>

          <input
            {...commonProps}
            type="number"
            placeholder=""
          />
        </div>
      );
    }


    return (
      <input
        {...commonProps}
        type={field.type || "text"}
        placeholder={field.label}
      />
    );
  };


  /*
  |--------------------------------------------------------------------------
  | Render Field Section
  |--------------------------------------------------------------------------
  */

  const renderFieldSection = (section) => {
    return (
      <section
        key={section.key}
        className="form-section"
      >
        <h2>{section.title}</h2>

        <div className="form-grid">
          {section.fields.map((field) => (
            <div
              key={field.name}
              className={
                field.type === "textarea"
                  ? "form-field full-width"
                  : "form-field"
              }
            >
              <label htmlFor={field.name}>
                {field.label}

                {field.required && (
                  <span className="required">
                    {" "}*
                  </span>
                )}
              </label>

              {renderField(field)}
            </div>
          ))}
        </div>
      </section>
    );
  };


  /*
  |--------------------------------------------------------------------------
  | Render Addresses
  |--------------------------------------------------------------------------
  */

  const renderAddresses = (section) => {
    return (
      <section
        key={section.key}
        className="form-section"
      >
        <div className="section-header">
          <div>
            <h2>{section.title}</h2>

            {section.maxAddresses && (
              <p>
                Maximum {section.maxAddresses} addresses,
                unique types (Permanent, Current, Office)
              </p>
            )}
          </div>

          <button
            type="button"
            className="add-button"
            onClick={addAddress}
          >
            + ADD ADDRESS
          </button>
        </div>


        {addresses.map((address, index) => (
          <div
            className="repeatable-card"
            key={index}
          >
            <div className="address-row">
              <select
                value={address.type}
                onChange={(event) =>
                  handleAddressChange(
                    index,
                    "type",
                    event.target.value
                  )
                }
              >
                <option value="">
                  Address Type
                </option>

                <option value="Permanent">
                  Permanent
                </option>

                <option value="Current">
                  Current
                </option>

                <option value="Office">
                  Office
                </option>
              </select>


              <textarea
                value={address.address}
                placeholder="Address"
                rows={2}
                onChange={(event) =>
                  handleAddressChange(
                    index,
                    "address",
                    event.target.value
                  )
                }
              />


              {addresses.length > 1 && (
                <button
                  type="button"
                  className="delete-button"
                  onClick={() =>
                    removeAddress(index)
                  }
                >
                  ×
                </button>
              )}
            </div>
          </div>
        ))}
      </section>
    );
  };


  /*
  |--------------------------------------------------------------------------
  | Render References
  |--------------------------------------------------------------------------
  */

  const renderReferences = (section) => {
    const maxReferences =
      loanConfig?.maxReferences || 5;

    return (
      <section
        key={section.key}
        className="form-section"
      >
        <div className="section-header">
          <div>
            <h2>{section.title}</h2>

            <p>
              Add at least one reference.
              Maximum {maxReferences} references allowed.
            </p>
          </div>

          <button
            type="button"
            className="add-button"
            onClick={addReference}
            disabled={
              references.length >= maxReferences
            }
          >
            + ADD REFERENCE
          </button>
        </div>


        {references.map((reference, index) => (
          <div
            className="repeatable-card"
            key={index}
          >
            <div className="repeatable-title">
              Reference {index + 1}
            </div>

            <div className="form-grid">
              <input
                value={reference.name}
                placeholder="Reference Name"
                onChange={(event) =>
                  handleReferenceChange(
                    index,
                    "name",
                    event.target.value
                  )
                }
              />

              <input
                value={reference.phone}
                placeholder="Reference Phone"
                onChange={(event) =>
                  handleReferenceChange(
                    index,
                    "phone",
                    event.target.value
                  )
                }
              />

              <input
                value={reference.relation}
                placeholder="Relation with Reference"
                onChange={(event) =>
                  handleReferenceChange(
                    index,
                    "relation",
                    event.target.value
                  )
                }
              />

              <textarea
                className="full-width"
                value={reference.address}
                placeholder="Reference Address"
                rows={2}
                onChange={(event) =>
                  handleReferenceChange(
                    index,
                    "address",
                    event.target.value
                  )
                }
              />
            </div>

            {references.length > 1 && (
              <button
                type="button"
                className="delete-button"
                onClick={() =>
                  removeReference(index)
                }
              >
                Remove
              </button>
            )}
          </div>
        ))}
      </section>
    );
  };


  /*
  |--------------------------------------------------------------------------
  | Render Co-Applicants
  |--------------------------------------------------------------------------
  */

  const renderCoApplicants = (section) => {
    const maxCoApplicants =
      loanConfig?.maxCoApplicants || 5;

    return (
      <section
        key={section.key}
        className="form-section"
      >
        <div className="section-header">
          <div>
            <h2>{section.title}</h2>

            <p>
              Maximum {maxCoApplicants}
              {" "}co-applicants allowed
            </p>
          </div>

          <button
            type="button"
            className="add-button"
            onClick={addCoApplicant}
            disabled={
              coApplicants.length >=
              maxCoApplicants
            }
          >
            + ADD CO-APPLICANT
          </button>
        </div>


        {coApplicants.map((applicant, index) => (
          <div
            className="repeatable-card"
            key={index}
          >
            <div className="repeatable-title">
              Co-Applicant {index + 1}
            </div>

            <div className="form-grid">
              <input
                value={applicant.name}
                placeholder="Name"
                onChange={(event) =>
                  handleCoApplicantChange(
                    index,
                    "name",
                    event.target.value
                  )
                }
              />

              <input
                value={applicant.phone}
                placeholder="Phone"
                onChange={(event) =>
                  handleCoApplicantChange(
                    index,
                    "phone",
                    event.target.value
                  )
                }
              />

              <input
                value={applicant.email}
                placeholder="Email"
                onChange={(event) =>
                  handleCoApplicantChange(
                    index,
                    "email",
                    event.target.value
                  )
                }
              />

              <input
                value={applicant.pan}
                placeholder="PAN"
                onChange={(event) =>
                  handleCoApplicantChange(
                    index,
                    "pan",
                    event.target.value
                  )
                }
              />

              <input
                value={applicant.relation}
                placeholder="Relation"
                onChange={(event) =>
                  handleCoApplicantChange(
                    index,
                    "relation",
                    event.target.value
                  )
                }
              />
            </div>

            {coApplicants.length > 1 && (
              <button
                type="button"
                className="delete-button"
                onClick={() =>
                  removeCoApplicant(index)
                }
              >
                Remove
              </button>
            )}
          </div>
        ))}
      </section>
    );
  };


  /*
  |--------------------------------------------------------------------------
  | Render Documents
  |--------------------------------------------------------------------------
  */

  const renderDocuments = (section) => {
    return (
      <section
        key={section.key}
        className="form-section"
      >
        <h2>{section.title}</h2>

        <div className="documents-grid">
          {(loanConfig?.documents || []).map(
            (document) => (
              <div
                className="document-card"
                key={document.key}
              >
                <span>
                  {document.label}
                </span>

                <label className="upload-button">
                  <input
                    type="file"
                    onChange={(event) =>
                      handleFieldChange(
                        `document_${document.key}`,
                        event.target.files?.[0] || null
                      )
                    }
                  />

                  📎 UPLOAD
                </label>
              </div>
            )
          )}
        </div>
      </section>
    );
  };


  /*
  |--------------------------------------------------------------------------
  | Render Section
  |--------------------------------------------------------------------------
  */

  const renderSection = (section) => {
    switch (section.type) {
      case "addresses":
        return renderAddresses(section);

      case "references":
      case "referencesAgriculture":
        return renderReferences(section);

      case "coApplicants":
      case "coApplicantsAgriculture":
        return renderCoApplicants(section);

      case "documents":
        return renderDocuments(section);

      default:
        return renderFieldSection(section);
    }
  };


  /*
  |--------------------------------------------------------------------------
  | Render
  |--------------------------------------------------------------------------
  */

  return (
    <div className="create-application">

      <ApplicationStepper
        currentStep={currentStep}
      />


      {currentStep === 1 && (
        <LoanTypeSelection
          loanTypes={LOAN_TYPES}
          selectedLoanType={selectedLoanType}
          onSelect={handleLoanTypeChange}
        />
      )}


      {currentStep >= 2 && loanConfig && (
        <>

          <div className="selected-loan-header">
            <div>
              <span>Loan Type</span>
              <h1>{loanConfig.label}</h1>
            </div>

            <button
              type="button"
              onClick={() => {
                setSelectedLoanType("");
                setCurrentStep(1);
              }}
            >
              Change Loan Type
            </button>
          </div>


          <form
            onSubmit={(event) => {
              event.preventDefault();
              handleNext();
            }}
          >
            {loanConfig.sections.map(
              (section) =>
                renderSection(section)
            )}


            <div className="form-actions">

              {currentStep > 1 && (
                <button
                  type="button"
                  onClick={handleBack}
                  className="back-button"
                >
                  ← BACK
                </button>
              )}

              <button
                type="submit"
                className="next-button"
              >
                NEXT →
              </button>

            </div>
          </form>

        </>
      )}

    </div>
  );
};


export default CreateApplication;
